import{_ as t,c as o,o as a,ae as s}from"./chunks/framework.CliRSA9F.js";const r="/images/overview.webp",p=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"features/podcast-details.md","filePath":"features/podcast-details.md"}'),i={name:"features/podcast-details.md"};function n(l,e,h,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><h2 id="your-show-at-a-glance" tabindex="-1">Your Show at a Glance <a class="header-anchor" href="#your-show-at-a-glance" aria-label="Permalink to &quot;Your Show at a Glance&quot;">​</a></h2><p>The Overview tab is your starting point for understanding how your podcast is performing. It pulls your most important signals — visibility, AI recommendations, search rankings, distribution, listener sentiment, and chart presence — into a single grid of summary widgets. Each widget shows the headline number and gives you a clear path into the detailed page behind it.</p><p><img src="'+r+'" alt="Overview Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>Traction</strong> in the sidebar — the Overview tab is shown by default.</p><hr><h2 id="visibility-score" tabindex="-1"><strong>Visibility Score</strong> <a class="header-anchor" href="#visibility-score" aria-label="Permalink to &quot;**Visibility Score**&quot;">​</a></h2><p>The most prominent widget is your <strong>Visibility Score</strong> — a number on a 0-10 scale that measures how discoverable your podcast is across Apple Podcasts, Spotify, Amazon Music, and YouTube Music. Higher scores mean your show is easier to find.</p><p>It isn&#39;t a single measurement. The score combines three things: your <strong>chart rankings</strong> on those platforms, your <strong>editorial features</strong> (curated collections and featured sections that platforms promote), and your <strong>search score</strong> (how many keywords you rank for and how high). Chart and editorial changes tend to move the score the most; search shifts move it more gradually. Because it blends all three, a change in your score can come from any of them — not just your keyword rankings.</p><p>Alongside the score you&#39;ll see:</p><ul><li><strong>Daily change</strong> — how your score shifted since the previous reading (for example, +0.12 or -0.05)</li><li><strong>Peer benchmark</strong> — the average visibility of comparable podcasts, plus how far ahead of your peers you are, when enough positioning data is available</li><li><strong>Rank</strong> — where you stand among all indexed podcasts (a lower rank number means better discoverability)</li></ul><p>A <strong>score trend</strong> chart tracks your visibility over time so you can see the impact of your optimization efforts at a glance. When a notable change occurs, a short explanation appears describing what moved your score.</p><p><strong>A note on movement</strong>: your score is measured partly in relation to other podcasts, so it can move even on days you change nothing. If a competitor climbs a chart, gains an editorial feature, or starts ranking for keywords you share, that can nudge your score and rank — the same way your own gains affect theirs. So treat a dip or bump as a prompt to look at what changed across your space, not only at what you did.</p><p>Click <strong>View analysis</strong> to open <a href="/features/visibility-progress.html">Visibility Progress</a>, which breaks down exactly how each factor contributes to your score. For a deeper explanation of how the score works, see <a href="/getting-started/visibility-score-explained.html">Visibility Score Explained</a>.</p><hr><h2 id="ai-visibility" tabindex="-1"><strong>AI Visibility</strong> <a class="header-anchor" href="#ai-visibility" aria-label="Permalink to &quot;**AI Visibility**&quot;">​</a></h2><p>When AI recommendation data is available, the <strong>AI Visibility</strong> widget shows how often ChatGPT, Claude, Perplexity, and Gemini recommend your podcast when listeners ask about your topics. Each assistant has its own row showing whether it currently mentions your show and for how many topics.</p><p>Click <strong>View analysis</strong> to open the full breakdown in <a href="/features/ai-mentions.html">AI Mentions</a>.</p><hr><h2 id="keyword-positions" tabindex="-1"><strong>Keyword Positions</strong> <a class="header-anchor" href="#keyword-positions" aria-label="Permalink to &quot;**Keyword Positions**&quot;">​</a></h2><p>The <strong>Keyword Positions</strong> widget tracks how many of your keywords sit in each ranking bucket over time, so you can watch your search footprint grow. Your tracked keywords are grouped into four position bands:</p><ul><li><strong>Top 3</strong> — your strongest, most visible rankings</li><li><strong>4-10</strong> — keywords ranking on the first page of results</li><li><strong>11-50</strong> — keywords with room to climb</li><li><strong>51-100</strong> — keywords on the edge of visibility</li></ul><p>Seeing more keywords move into the Top 3 and 4-10 bands over time is a strong sign your optimization efforts are working. Click <strong>View analysis</strong> to explore your full keyword rankings in <a href="/features/show-visibility.html">Show Visibility</a>.</p><hr><h2 id="distribution" tabindex="-1"><strong>Distribution</strong> <a class="header-anchor" href="#distribution" aria-label="Permalink to &quot;**Distribution**&quot;">​</a></h2><p>The <strong>Distribution</strong> widget shows where your show is listed and whether each listing is healthy. It covers your RSS feed plus your presence on Apple Podcasts, Spotify, Amazon Music, and YouTube Music, with a status indicator for each so you can spot problems at a glance.</p><p>If PodSEO doesn&#39;t detect a dedicated website for your show, this widget also flags it, since a custom website gives your podcast its own Google-indexed pages that platforms alone can&#39;t provide.</p><p>For a full diagnostic — feed analysis, platform listings, website setup, and feed performance — open <a href="/features/distribution-health.html">Distribution Health</a>.</p><hr><h2 id="reviews-featured-placements-top-charts-and-ratings" tabindex="-1"><strong>Reviews, Featured Placements, Top Charts, and Ratings</strong> <a class="header-anchor" href="#reviews-featured-placements-top-charts-and-ratings" aria-label="Permalink to &quot;**Reviews, Featured Placements, Top Charts, and Ratings**&quot;">​</a></h2><p>The lower section of the grid loads a set of summary panels that give you a quick read on listener sentiment and external visibility:</p><ul><li><strong>Reviews</strong> — your most recent listener reviews</li><li><strong>Featured placements</strong> — a summary of your editorial visibility across platforms</li><li><strong>Top charts</strong> — your current chart presence</li><li><strong>Ratings</strong> — your star ratings on Apple Podcasts and Spotify</li></ul><p>Each panel links through to its detailed page so you can dig deeper — your reviews and ratings in <a href="/features/ratings-and-reviews.html">Ratings &amp; Reviews</a>, your editorial placements in <a href="/features/my-placements.html">Editorial Presence</a>, and your chart standings in <a href="/features/my-charts.html">My Charts</a>.</p><hr><p>The Overview tab is designed to be the first place you check each day. Scan the headline numbers to see what&#39;s changed, then use the <strong>View analysis</strong> links to jump straight into whichever area needs your attention.</p>',35)])])}const y=t(i,[["render",n]]);export{p as __pageData,y as default};
